INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Muss jede Variable bei der Deklaration initialisiert werden?', 2, '[{"text": "Nein", "correct": true, "because": "Kann später zugewiesen werden"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einer Deklaration?', 3, '[{"text": "Speicherplatz reservieren", "correct": true, "because": "Definiert Variable"}, {"text": "Code ausführen", "correct": false, "because": "Nur Definition"}, {"text": "UI gestalten", "correct": false, "because": "Anderer Bereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zu einer Deklaration?', 5, '[{"text": "Datentyp", "correct": true, "because": "Bestimmt Art des Werts"}, {"text": "Name", "correct": true, "because": "Identifiziert Variable"}, {"text": "Farbschema", "correct": false, "because": "Irrelevant"}, {"text": "Netzwerkprotokoll", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Datentypen sind sprachabhängig. b) Initialisierung ist optional.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "a) variiert, b) nicht zwingend"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch richtig"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "Beides richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Deklaration einer Variable?', 4, '[{"text": "Datentyp", "correct": false, "because": "Definiert Struktur"}, {"text": "Namenskonvention", "correct": false, "because": "Fördert Lesbarkeit"}, {"text": "Bildauflösung", "correct": true, "because": "Kein Zusammenhang"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob jede Sprache Datentypen erzwingt?', 2, '[{"text": "Nein", "correct": true, "because": "Dynamische Typisierung möglich"}, {"text": "Ja", "correct": false, "because": "Nicht universell"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Datentyp wähle ich für eine Ganzzahl?', 3, '[{"text": "int", "correct": true, "because": "Für ganze Zahlen geeignet"}, {"text": "float", "correct": false, "because": "Für Dezimalzahlen"}, {"text": "string", "correct": false, "because": "Für Text"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte sind bei der Initialisierung wichtig?', 5, '[{"text": "Korrekter Wert", "correct": true, "because": "Vermeidet undefinierte Zustände"}, {"text": "Passender Datentyp", "correct": true, "because": "Sichert Kompatibilität"}, {"text": "UI-Layout", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Deklaration reserviert Speicher. b) Sie ist immer mit Wertzuweisung. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist optional"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine Deklaration?', 4, '[{"text": "Variablenname", "correct": false, "because": "Identifikation nötig"}, {"text": "Datentyp", "correct": false, "because": "Definiert Typ"}, {"text": "Grafiksoftware", "correct": true, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist int für Dezimalzahlen geeignet?', 2, '[{"text": "Nein", "correct": true, "because": "Nur ganze Zahlen"}, {"text": "Ja", "correct": false, "because": "Float nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine klare Deklaration?', 4, '[{"text": "Fehlervermeidung", "correct": true, "because": "Typensicherheit"}, {"text": "Lesbarkeit", "correct": true, "because": "Code verständlicher"}, {"text": "Datenkompression", "correct": false, "because": "Kein Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Deklaration die Ausführung verlangsamt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Nur Definition, kein Laufzeitproblem"}, {"text": "Ja", "correct": false, "because": "Kein direkter Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Wahl eines Datentyps?', 3, '[{"text": "Passgenauigkeit", "correct": true, "because": "Sichert Funktion"}, {"text": "Schnelle Definition", "correct": false, "because": "Qualität zählt"}, {"text": "Farbanpassung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Deklaration hilft beim Debuggen. b) Sie ist nur für große Programme.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "Auch kleine Programme profitieren"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Risiken gibt es ohne Initialisierung?', 5, '[{"text": "Undefinierte Werte", "correct": true, "because": "Kann Fehler verursachen"}, {"text": "Unvorhersehbares Verhalten", "correct": true, "because": "Wert unsicher"}, {"text": "Schnellere Ausführung", "correct": false, "because": "Kein Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Deklaration unwichtig?', 3, '[{"text": "Datentyp", "correct": false, "because": "Definiert Struktur"}, {"text": "Name", "correct": false, "because": "Identifikation nötig"}, {"text": "Serverkonfiguration", "correct": true, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann ich eine Variable ohne Typ deklarieren?', 3, '[{"text": "Ja", "correct": true, "because": "In dynamischen Sprachen"}, {"text": "Nein", "correct": false, "because": "Sprachabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Initialisierung Speicher spart?', 2, '[{"text": "Nein", "correct": true, "because": "Nur Wertzuweisung"}, {"text": "Ja", "correct": false, "because": "Kein direkter Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Datentyp wähle ich für Text?', 4, '[{"text": "string", "correct": true, "because": "Für Zeichenketten geeignet"}, {"text": "int", "correct": false, "because": "Für Zahlen"}, {"text": "bool", "correct": false, "because": "Für Wahr/Falsch"}]');
